"use client";
import { useState, useEffect } from "react";
import { Card } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Button } from "@/components/ui/button";
import { Separator } from "@/components/ui/separator";
import { getProfile, updateProfile, uploadAvatar } from "@/app/api/doctor/profile";

const initialProfile = {
  avatarUrl: null,
  fullName: "",
  email: "",
  phone: "",
  gender: "",
  age: "",
  address: { country: "" },
  qualifications: [],
  availability: { days: [], timeSlots: [] },
  specialization: "",
  experience: "",
};

export default function DoctorProfilePage() {
  const [profile, setProfile] = useState(initialProfile);
  const [avatarUrl, setAvatarUrl] = useState(profile.avatarUrl);
  const [uploading, setUploading] = useState(false);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    async function fetchProfile() {
      const id = localStorage.getItem("userId");
      setLoading(true);
      try {
        const data = await getProfile(id);
        setProfile({
          ...initialProfile,
          ...data,
          address: { ...initialProfile.address, ...data.address },
          availability: { ...initialProfile.availability, ...data.availability },
        });
        setAvatarUrl(data.avatarUrl);
      } catch (err) {
        console.error(err);
      }
      setLoading(false);
    }
    fetchProfile();
  }, []);

  const handleChange = (field, value) => setProfile((prev) => ({ ...prev, [field]: value }));
  const handleAddressChange = (field, value) => setProfile((prev) => ({ ...prev, address: { ...prev.address, [field]: value } }));
  const handleAvailabilityChange = (field, value) => setProfile((prev) => ({ ...prev, availability: { ...prev.availability, [field]: value } }));
  
  const handleQualificationsChange = (idx, value) => {
    const qualifications = [...profile.qualifications];
    qualifications[idx] = value;
    setProfile((prev) => ({ ...prev, qualifications }));
  };
  
  const addQualification = () => setProfile((prev) => ({ ...prev, qualifications: [...prev.qualifications, ""] }));
  const removeQualification = (idx) => setProfile((prev) => ({ ...prev, qualifications: prev.qualifications.filter((_, i) => i !== idx) }));

  const handleAvatarUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    setUploading(true);
    const formData = new FormData();
    formData.append("avatar", file);
    try {
      const data = await uploadAvatar(formData, file.name);
      setAvatarUrl(data.avatarUrl);
      setProfile((prev) => ({ ...prev, avatarUrl: data.avatarUrl }));
    } catch (err) {
      console.error("Upload failed", err);
    }
    setUploading(false);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setSaving(true);
    try {
      await updateProfile(profile);
      alert("Profile saved!");
    } catch (err) {
      alert("Failed to save profile");
    }
    setSaving(false);
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-blue-50 via-white to-blue-100 flex items-center justify-center">
        <div className="text-xl font-medium text-blue-600">Loading profile...</div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 via-white to-blue-100 flex items-center justify-center px-2 py-10">
      <div className="w-full max-w-2xl bg-white/95 p-7 sm:p-10 rounded-3xl shadow-2xl border-0 max-h-[calc(100vh-4rem)] overflow-auto">
        <h1 className="text-3xl font-extrabold text-blue-800 mb-8 drop-shadow text-center">
          Doctor Profile
        </h1>
        
        <form onSubmit={handleSubmit} className="space-y-8">
          {/* Profile Header - Avatar & Primary Details */}
          <div className="flex items-center gap-8 mb-8">
            <div className="relative">
              <Avatar className="w-24 h-24 ring-2 ring-blue-500 shadow-lg bg-blue-50">
                <AvatarImage
                  src={
                    avatarUrl?.startsWith("http")
                      ? avatarUrl
                      : avatarUrl
                      ? `http://localhost:5000${avatarUrl}`
                      : "/default-avatar.png"
                  }
                  alt={profile.fullName}
                  onError={(e) => { e.currentTarget.src = "/default-avatar.png"; }}
                />
                <AvatarFallback className="text-2xl font-bold text-blue-700">
                  {profile?.fullName?.[0] || "U"}
                </AvatarFallback>
              </Avatar>
              <label className="absolute bottom-0 right-0 bg-white rounded-full p-1 shadow-md border cursor-pointer hover:bg-blue-100 transition">
                <input type="file" accept="image/*" className="hidden" onChange={handleAvatarUpload} />
                <span className="text-xs">{uploading ? "..." : "✏️"}</span>
              </label>
            </div>
            <div className="grid grid-cols-1 gap-3 w-full">
              <Input
                placeholder="Full Name"
                value={profile.fullName}
                onChange={(e) => handleChange("fullName", e.target.value)}
                required
                className="rounded-lg shadow bg-blue-50 border-blue-100 focus:ring-2 focus:ring-blue-300"
              />
              <Input
                placeholder="Specialization"
                value={profile.specialization}
                onChange={(e) => handleChange("specialization", e.target.value)}
                required
                className="rounded-lg shadow bg-blue-50 border-blue-100 focus:ring-2 focus:ring-blue-300"
              />
            </div>
          </div>

          {/* Personal & Contact Details */}
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 mb-6">
            <Input
              placeholder="Email"
              type="email"
              value={profile.email}
              onChange={(e) => handleChange("email", e.target.value)}
              disabled
              required
              className="rounded-lg shadow bg-gray-100 text-gray-400 border-gray-200"
            />
            <Input
              placeholder="Phone"
              value={profile.phone}
              onChange={(e) => handleChange("phone", e.target.value)}
              required
              className="rounded-lg shadow bg-blue-50 border-blue-100 focus:ring-2 focus:ring-blue-300"
            />
            <Input
              placeholder="Gender"
              value={profile.gender}
              onChange={(e) => handleChange("gender", e.target.value)}
              className="rounded-lg shadow bg-blue-50 border-blue-100 focus:ring-2 focus:ring-blue-300"
            />
            <Input
              placeholder="Age"
              type="number"
              value={profile.age}
              onChange={(e) => handleChange("age", e.target.value)}
              className="rounded-lg shadow bg-blue-50 border-blue-100 focus:ring-2 focus:ring-blue-300"
            />
            <div className="sm:col-span-2">
              <Input
                placeholder="Country"
                value={profile.address.country}
                onChange={(e) => handleAddressChange("country", e.target.value)}
                className="rounded-lg shadow bg-blue-50 border-blue-100 focus:ring-2 focus:ring-blue-300"
              />
            </div>
          </div>

          <Separator className="my-6" />

          {/* Qualifications */}
          <div>
            <h2 className="text-lg font-bold text-blue-900 mb-4 border-l-4 border-blue-200 pl-2">
              Qualifications
            </h2>
            {profile.qualifications.map((q, idx) => (
              <div key={idx} className="flex gap-2 mb-2">
                <Input
                  value={q}
                  onChange={(e) => handleQualificationsChange(idx, e.target.value)}
                  placeholder="Qualification"
                  className="rounded-lg shadow bg-blue-50 border-blue-100 focus:ring-2 focus:ring-blue-300"
                />
                <Button
                  type="button"
                  variant="outline"
                  className="rounded-full px-3"
                  onClick={() => removeQualification(idx)}
                >
                  -
                </Button>
              </div>
            ))}
            <Button
              type="button"
              variant="secondary"
              className="mt-2 rounded-full"
              onClick={addQualification}
            >
              + Add Qualification
            </Button>
          </div>

          <Separator className="my-6" />

          {/* Availability */}
          <div>
            <h2 className="text-lg font-bold text-blue-900 mb-4 border-l-4 border-blue-200 pl-2">
              Availability
            </h2>
            <div className="flex flex-col sm:flex-row items-center gap-4">
              <span className="font-medium text-gray-700">Start Time</span>
              <Input
                type="time"
                value={profile.availability.timeSlots[0]?.split("-")[0] || ""}
                onChange={(e) => {
                  const end = profile.availability.timeSlots[0]?.split("-")[1] || "";
                  const start = e.target.value;
                  handleAvailabilityChange("timeSlots", [`${start}-${end}`]);
                }}
                className="rounded-lg bg-blue-50 border-blue-100"
              />
              <span className="font-medium text-gray-700">End Time</span>
              <Input
                type="time"
                value={profile.availability.timeSlots[0]?.split("-")[1] || ""}
                onChange={(e) => {
                  const start = profile.availability.timeSlots[0]?.split("-")[0] || "";
                  const end = e.target.value;
                  handleAvailabilityChange("timeSlots", [`${start}-${end}`]);
                }}
                className="rounded-lg bg-blue-50 border-blue-100"
              />
            </div>
          </div>

          <Separator className="my-6" />

          {/* Experience */}
          <div>
            <h2 className="text-lg font-bold text-blue-900 mb-4 border-l-4 border-blue-200 pl-2">
              Experience
            </h2>
            <Input
              placeholder="Experience in years"
              type="number"
              value={profile.experience}
              onChange={(e) => handleChange("experience", e.target.value)}
              className="rounded-lg shadow bg-blue-50 border-blue-100 focus:ring-2 focus:ring-blue-300"
            />
          </div>

          {/* Submit Button */}
          <Button
            type="submit"
            className="w-full rounded-full mt-8 py-3 font-bold bg-blue-700 text-white hover:bg-blue-800 shadow-lg transition disabled:opacity-60"
            disabled={saving}
          >
            {saving ? "Saving..." : "Save Changes"}
          </Button>
        </form>
      </div>
    </div>
  );
}
